// Minimal test-only stub of @opencode-ai/plugin, so the plugin module can be
// imported by node:test without the real package installed. Only the runtime
// surface used by apple-music.ts is implemented: `tool()` and `tool.schema`.
export function tool(definition) {
  return definition
}

const chainable = { optional: () => chainable, describe: () => chainable }

tool.schema = {
  enum: () => chainable,
  string: () => chainable,
  boolean: () => chainable,
  number: () => chainable,
  object: () => chainable,
}

export default { tool }
